// Regrouper le scénario de connexion avec les deux champs vides.
describe('Authentification Swag Labs', () => {
  // Définir le scénario de formulaire soumis sans identifiants.
  it('champs vides → reste sur la page de connexion et affiche une erreur', () => {
    // Ouvrir la page de connexion Swag Labs.
    cy.visit('/');

    // Soumettre le formulaire sans remplir le nom d'utilisateur ni le mot de passe.
    cy.get('[data-test="login-button"]').click();

    // Vérifier que le navigateur reste sur la page de connexion.
    cy.location('pathname').should('eq', '/');
    // Vérifier que l'erreur est visible et demande le nom d'utilisateur.
    cy.get('[data-test="error"]').should('be.visible').and('contain', 'Username is required');
  });
});
